.darma-loader-darma-b16-voice-waveform-listen { --accent: var(--loader-color, #7c3aed); --accent-2: var(--loader-secondary-color, #f0abfc); width: var(--loader-size, 132px); height: calc(var(--loader-size, 132px) * .34); position: relative; display: flex; gap: 2.5%; align-items: center; justify-content: flex-end; }
.darma-loader-darma-b16-voice-waveform-listen .darma-loader-darma-b16-voice-waveform-listen__mic { position: absolute; left: 0; top: 18%; width: 12%; height: 64%; border-radius: 999px 999px 40% 40%; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b16-voice-waveform-listen-voice-mic calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
.darma-loader-darma-b16-voice-waveform-listen .darma-loader-darma-b16-voice-waveform-listen__mic::after { content: ''; position: absolute; left: 20%; right: 20%; top: 104%; height: 22%; border-radius: 0 0 999px 999px; box-shadow: inset 0 -3px 0 var(--accent); }
.darma-loader-darma-b16-voice-waveform-listen span { width: 8%; border-radius: 999px; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b16-voice-waveform-listen-voice-wave calc(var(--loader-speed, 1s) * 1.1) ease-in-out infinite; }
.darma-loader-darma-b16-voice-waveform-listen span:nth-of-type(1) { height: 34%; animation-delay: calc(var(--loader-speed, 1s) * -.9); }
.darma-loader-darma-b16-voice-waveform-listen span:nth-of-type(2) { height: 58%; animation-delay: calc(var(--loader-speed, 1s) * -.75); }
.darma-loader-darma-b16-voice-waveform-listen span:nth-of-type(3) { height: 88%; animation-delay: calc(var(--loader-speed, 1s) * -.6); }
.darma-loader-darma-b16-voice-waveform-listen span:nth-of-type(4) { height: 100%; animation-delay: calc(var(--loader-speed, 1s) * -.45); }
.darma-loader-darma-b16-voice-waveform-listen span:nth-of-type(5) { height: 88%; animation-delay: calc(var(--loader-speed, 1s) * -.3); }
.darma-loader-darma-b16-voice-waveform-listen span:nth-of-type(6) { height: 58%; animation-delay: calc(var(--loader-speed, 1s) * -.15); }
.darma-loader-darma-b16-voice-waveform-listen span:nth-of-type(7) { height: 34%; }
@keyframes darma-loader-darma-b16-voice-waveform-listen-voice-wave { 0%, 100% { transform: scaleY(.28); opacity: .55; } 50% { transform: scaleY(1); opacity: 1; } }
@keyframes darma-loader-darma-b16-voice-waveform-listen-voice-mic { 0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent) 45%, transparent); } 50% { transform: scale(1.06); box-shadow: 0 0 0 8px color-mix(in srgb, var(--accent) 0%, transparent); } }

